let lang="de";const toast=document.getElementById("toast");
function notify(s){toast.textContent=s;toast.classList.add("show");setTimeout(()=>toast.classList.remove("show"),1800)}
function render(){document.documentElement.lang=lang;document.querySelectorAll("[data-i18n]").forEach(el=>{const k=el.dataset.i18n;if(dict[lang][k])el.innerHTML=dict[lang][k]})}
document.getElementById("lang").addEventListener("click",()=>{lang=lang==="de"?"en":"de";render()});
document.querySelectorAll("[data-go]").forEach(el=>el.addEventListener("click",()=>notify((lang==="de"?"Modul folgt: ":"Module planned: ")+el.dataset.go)));
document.querySelectorAll("[data-theme]").forEach(el=>el.addEventListener("click",()=>{const themes={midnight:["#080b14","#8b7cff"],aurora:["#071a20","#48c9ad"],crimson:["#170b12","#d85b78"]};const t=themes[el.dataset.theme];document.documentElement.style.setProperty("--bg",t[0]);document.documentElement.style.setProperty("--accent",t[1]);notify("Theme: "+el.dataset.theme)}));
render();
